// Pinned r186 adapter: isolate access to Three's backend texture handle here.
import * as T from 'three/webgpu';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {RoomEnvironment} from 'three/addons/environments/RoomEnvironment.js';
import {mapCitySurface} from '../city/surface-uv.js';
import {citySurfaceNodes} from '../city/surface-nodes.js';
import {uniform} from 'three/tsl';
import {MAPS} from './pack.js';
export class ProductionPreview{
 async init(mount){this.renderer=new T.WebGPURenderer({antialias:true});const r=this.renderer;await r.init();if(!r.backend.isWebGPUBackend)throw Error('WebGPU is required for this lab');this.device=r.backend.device;this.device.addEventListener('uncapturederror',e=>{document.body.dataset.error=e.error.message;console.error(e.error.message);});r.setPixelRatio(Math.min(devicePixelRatio,1.5));r.toneMapping=T.ACESFilmicToneMapping;r.toneMappingExposure=1;r.shadowMap.enabled=true;r.shadowMap.type=T.PCFShadowMap;mount.append(r.domElement);this.scene=new T.Scene();this.scene.background=new T.Color(0xc2cbcb);this.camera=new T.PerspectiveCamera(39,1,.05,400);this.camera.position.set(1.2,1.7,3.8);this.controls=new OrbitControls(this.camera,r.domElement);this.controls.target.set(0,1.25,0);this.controls.update();this.controls.addEventListener('change',()=>this.dirty=true);
 const shape=new T.Shape();shape.moveTo(-1,-1);shape.lineTo(1,-1);shape.lineTo(1,1);shape.lineTo(-1,1);shape.closePath();const g=new T.ExtrudeGeometry(shape,{depth:.12,bevelEnabled:true,bevelSize:.025,bevelThickness:.025,bevelSegments:3,steps:1});mapCitySurface(g,{index:0},{variation:0});this.mesh=new T.Mesh(g,new T.MeshStandardNodeMaterial({color:0xaaa99c,roughness:.5}));this.mesh.position.y=1.25;this.mesh.castShadow=this.mesh.receiveShadow=true;this.scene.add(this.mesh);const floor=new T.Mesh(new T.PlaneGeometry(60,60),new T.MeshStandardNodeMaterial({color:0x929b94,roughness:.95}));floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;this.scene.add(floor);this.floor=floor;
 this.sun=new T.DirectionalLight(0xffefdf,3.1);this.sun.position.set(-8,12,7);this.sun.castShadow=true;this.sun.shadow.mapSize.set(2048,2048);Object.assign(this.sun.shadow.camera,{left:-4,right:4,top:4,bottom:-4,near:.1,far:40});this.sun.shadow.normalBias=.008;this.scene.add(this.sun,new T.HemisphereLight(0xd9e8f4,0x665f50,.35));this.pmrem=new T.PMREMGenerator(r);const room=new RoomEnvironment();this.environment=this.pmrem.fromScene(room,.04);room.dispose();this.scene.environment=this.environment.texture;this.scene.environmentIntensity=.4;this.channel=uniform(0);this.textures=[];this.dirty=true;
 this.observer=new ResizeObserver(()=>{this.camera.aspect=mount.clientWidth/mount.clientHeight;this.camera.updateProjectionMatrix();r.setSize(mount.clientWidth,mount.clientHeight);this.dirty=true;});this.observer.observe(mount);r.setAnimationLoop(async()=>{if(!this.dirty||this.rendering||this.updating)return;this.rendering=true;this.dirty=false;try{await r.renderAsync(this.scene,this.camera);await this.device.queue.onSubmittedWorkDone();document.body.dataset.frame=String(Number(document.body.dataset.frame||0)+1);}catch(e){document.body.dataset.error=e.message;console.error(e);}finally{this.rendering=false;}});return this;
 }
 async shape(kind='panel'){await this.idle();this.updating=true;try{let g;if(kind==='sphere'){g=new T.SphereGeometry(1,80,48);const uv=g.attributes.uv;for(let i=0;i<uv.count;i++)uv.setXY(i,uv.getX(i)*6,uv.getY(i)*4);g.userData.cityMetric=true;}else if(kind==='cube')g=new T.BoxGeometry(1.7,1.7,1.7,1,1,1);else{const shape=new T.Shape();shape.moveTo(-1,-1);shape.lineTo(1,-1);shape.lineTo(1,1);shape.lineTo(-1,1);shape.closePath();g=new T.ExtrudeGeometry(shape,{depth:.12,bevelEnabled:true,bevelSize:.025,bevelThickness:.025,bevelSegments:3,steps:1});}mapCitySurface(g,{index:0},{variation:0});this.mesh.geometry.dispose();this.mesh.geometry=g;this.dirty=true;}finally{this.updating=false;}}
 async idle(){while(this.rendering)await new Promise(resolve=>requestAnimationFrame(resolve));}
 texture(id,levels){const first=levels[0],t=new T.DataTexture(first.data,first.width,first.height,T.RGBAFormat);t.colorSpace=id==='color'?T.SRGBColorSpace:T.NoColorSpace;t.wrapS=t.wrapT=T.ClampToEdgeWrapping;t.generateMipmaps=false;t.mipmaps=levels;t.minFilter=T.LinearMipmapLinearFilter;t.magFilter=T.LinearFilter;t.anisotropy=4;t.needsUpdate=true;return t;}
 async apply(pack){await this.idle();this.updating=true;try{const begin=performance.now(),textures=Object.fromEntries(MAPS.map(id=>[id,this.texture(id,pack.maps[id])])),m=this.material(textures,pack.manifest.recipe,pack.manifest.atlas);await this.replace(m,textures);return performance.now()-begin;}finally{this.updating=false;}}
 material(t,recipe,atlas={columns:4,rows:2,guardFraction:.125}){const m=new T.MeshStandardNodeMaterial({map:t.color,normalMap:t.normal,roughnessMap:t.surface,metalnessMap:t.surface,aoMap:t.surface,roughness:1,metalness:1,vertexColors:true});m.userData.citySurface={tileMeters:2,atlasColumns:atlas.columns,atlasRows:atlas.rows,atlasGuard:atlas.guardFraction,wear:0,variation:.025,dirt:[.28,.3,.27],relief:1,buildingWeather:recipe?.weather};return citySurfaceNodes(m,{preview:this.channel});}
 async applyGPU(result){await this.idle();this.updating=true;try{const begin=performance.now(),textures={};for(const id of MAPS){textures[id]=this.texture(id,result.levels.map(l=>({width:l.width,height:l.height,data:new Uint8Array(l.width*l.height*4)})));await this.renderer.initTexture(textures[id]);}const encoder=this.device.createCommandEncoder();for(const id of MAPS){const texture=this.renderer.backend.get(textures[id]).texture;if(!texture)throw Error('Pinned WebGPU texture adapter is unavailable');for(let i=0;i<result.levels.length;i++){const l=result.levels[i];if((l.width*4)%256===0)encoder.copyBufferToTexture({buffer:l.buffers[id],bytesPerRow:l.width*4,rowsPerImage:l.height},{texture,mipLevel:i},{width:l.width,height:l.height});else for(let y=0;y<l.height;y++)encoder.copyBufferToTexture({buffer:l.buffers[id],offset:y*l.width*4},{texture,mipLevel:i,origin:{x:0,y,z:0}},{width:l.width,height:1});}}this.device.queue.submit([encoder.finish()]);await this.device.queue.onSubmittedWorkDone();await this.replace(this.material(textures,result.recipe,result.atlas),textures);return performance.now()-begin;}finally{this.updating=false;}}
 async replace(material,textures){const old=this.mesh.material,previous=this.textures;this.mesh.material=material;this.textures=Object.values(textures);await this.renderer.renderAsync(this.scene,this.camera);await this.device.queue.onSubmittedWorkDone();old.dispose();previous.forEach(t=>t.dispose());document.body.dataset.frame=String(Number(document.body.dataset.frame||0)+1);this.dirty=true;}
 zone(id){const a=this.mesh.geometry.attributes.uv1;for(let i=0;i<a.count;i++)a.setX(i,Number(id));a.needsUpdate=true;this.dirty=true;}
 inspect(id){this.channel.value=Number(id);this.dirty=true;}
 light(id){this.sun.position.set(...(id==='raking'?[8,3,3]:[-8,12,7]));this.dirty=true;}
 dispose(){this.observer?.disconnect();this.renderer?.setAnimationLoop(null);this.controls?.dispose();this.mesh?.geometry.dispose();this.mesh?.material.dispose();this.textures?.forEach(t=>t.dispose());this.floor?.geometry.dispose();this.floor?.material.dispose();this.environment?.dispose();this.pmrem?.dispose();this.renderer?.dispose();}
}
